\begin{thema}{Γ}
Μια συνεχής συνάρτηση $f: \mathbb{R} \to \mathbb{R}$ ικανοποιεί τη σχέση $f(x) = e^x + 2\dint_0^1 f(t)dt$ για κάθε $x \in \mathbb{R}$.
\begin{erwthma}
  \item Να αποδείξετε ότι  $\dint_0^1 f(t)dt = 1-e$ και στη συνέχεια να γράψετε τον τύπο της $f(x)$.
  \item Να υπολογίσετε το όριο $\lim\limits_{x \to 0} \dfrac{f(x) - f(0)}{x}$.
  \item Να υπολογίσετε το όριο $\lim\limits_{x \to +\infty} \dfrac{f(x)}{f(x+1)}$.
  \item Nα υπολογίσετε το όριο $\lim\limits_{x \to +\infty} f\left(\dfrac{\ln x}{x}\right)$.
\end{erwthma}
\end{thema}
